package aws

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
)

// Resource is any strongly typed AWS CloudFormation resource as generated by
// goformation — s3.Bucket, iam.Role, ec2.VPC, and every other type under
// github.com/awslabs/goformation/v7/cloudformation/... They all satisfy it via
// their generated AWSCloudFormationType method, so nothing is implemented by
// hand.
//
// The Cloud Control API speaks exactly these type names and property shapes,
// which is what makes this package type safe end to end.
//
// This is the plain interface, used where a resource arrives as a value —
// Instance.Add. The CRUD functions use ResourceOf, which additionally ties the
// value to its Go type.
type Resource interface {
	// AWSCloudFormationType returns the Cloud Control type name, e.g.
	// "AWS::S3::Bucket".
	AWSCloudFormationType() string
}

// ResourceOf constrains a type parameter to a goformation resource. It reads as
// "P is a pointer to T, and that pointer is a Resource".
//
// goformation puts AWSCloudFormationType on the pointer receiver, which is why
// the constraint is written this way; the payoff is that every generic function
// here derives the Cloud Control type name from the type parameter alone, with
// no registry and no reflection:
//
//	aws.TypeName[*s3.Bucket]() // "AWS::S3::Bucket"
type ResourceOf[T any] interface {
	*T
	Resource
}

// TypeName returns the Cloud Control type name of a resource type, e.g.
// "AWS::S3::Bucket". It never touches the host.
func TypeName[P ResourceOf[T], T any]() string {
	var zero T
	return P(&zero).AWSCloudFormationType()
}

// marshalResource renders a resource into the DesiredState document that Cloud
// Control expects.
//
// goformation's MarshalJSON emits a CloudFormation template fragment —
// {"Type": ..., "Properties": {...}} — while Cloud Control wants the bare
// properties object, so the Properties sub-document is lifted back out. Going
// through goformation's own marshaller (rather than re-encoding the struct) is
// what keeps every one of its ~1200 resource types working unmodified.
func marshalResource(resource Resource) (json.RawMessage, error) {
	if resource == nil {
		return nil, fmt.Errorf("desired state must not be nil")
	}
	typeName := resource.AWSCloudFormationType()
	raw, err := json.Marshal(resource)
	if err != nil {
		return nil, fmt.Errorf("marshal %s: %w", typeName, err)
	}
	var fragment struct {
		Properties json.RawMessage `json:"Properties"`
	}
	if err := json.Unmarshal(raw, &fragment); err != nil {
		return nil, fmt.Errorf("extract %s properties: %w", typeName, err)
	}
	if len(fragment.Properties) == 0 {
		return json.RawMessage("{}"), nil
	}
	return fragment.Properties, nil
}

// unmarshalState fills a typed resource from a Cloud Control resource state
// document.
//
// Two things stop the state document being handed straight to goformation:
// its generated UnmarshalJSON expects the {"Type","Properties"} template
// wrapper, and it decodes with DisallowUnknownFields. Cloud Control returns a
// bare properties object that routinely carries read-only attributes the
// writable struct does not model (Arn, VpcId, DualStackDomainName, ...), so a
// direct decode fails on the first one.
//
// So: drop the keys T does not declare, wrap the rest in the fragment
// goformation wants, and let its own unmarshaller do the work. Nested property
// structs have no custom decoder, so unknown fields deeper in the tree are
// ignored by encoding/json as usual.
func unmarshalState[P ResourceOf[T], T any](state []byte) (P, error) {
	typeName := TypeName[P, T]()

	var document map[string]json.RawMessage
	if err := json.Unmarshal(state, &document); err != nil {
		return nil, fmt.Errorf("decode %s state: not a JSON object: %w", typeName, err)
	}

	known := make(map[string]json.RawMessage, len(document))
	for name := range writableProperties[T]() {
		if raw, ok := document[name]; ok {
			known[name] = raw
		}
	}

	properties, err := json.Marshal(known)
	if err != nil {
		return nil, fmt.Errorf("re-encode %s properties: %w", typeName, err)
	}
	fragment, err := json.Marshal(map[string]json.RawMessage{"Properties": properties})
	if err != nil {
		return nil, fmt.Errorf("re-encode %s fragment: %w", typeName, err)
	}

	resource := P(new(T))
	if err := json.Unmarshal(fragment, resource); err != nil {
		return nil, fmt.Errorf("decode %s state: %w", typeName, err)
	}
	return resource, nil
}

// writableProperties returns the JSON property names T declares, i.e. the
// writable CloudFormation properties. goformation tags its bookkeeping fields
// (AWSCloudFormationDeletionPolicy and friends) with `json:"-"`, so they drop
// out here for free.
func writableProperties[T any]() map[string]struct{} {
	t := reflect.TypeFor[T]()
	if t.Kind() != reflect.Struct {
		return nil
	}
	names := make(map[string]struct{}, t.NumField())
	for i := range t.NumField() {
		field := t.Field(i)
		if field.PkgPath != "" {
			continue // unexported
		}
		name, _, _ := strings.Cut(field.Tag.Get("json"), ",")
		if name == "" {
			name = field.Name
		}
		if name == "-" {
			continue
		}
		names[name] = struct{}{}
	}
	return names
}

// State is a resource as the Cloud Control API currently sees it: the typed
// properties plus the untouched state document.
//
// Reach for it when a check needs a read-only attribute. goformation models only
// writable properties, so values AWS assigns — an ARN, a VpcId, an instance
// state — exist in Document but have no field on Properties.
type State[T any] struct {
	// Identifier is the resource's primary identifier.
	Identifier string
	// Properties is the typed view, with read-only attributes dropped.
	Properties *T
	// Document is the raw Cloud Control state, including read-only attributes.
	Document json.RawMessage
}

// Attr returns a top-level attribute from the raw state document, which is the
// only way to reach read-only values such as "Arn":
//
//	state, err := aws.ReadState[*s3.Bucket]("my-bucket")
//	arn, ok := state.Attr("Arn")
//
// JSON strings are returned unquoted; any other value is returned as its JSON
// encoding. ok is false when the attribute is absent.
func (s *State[T]) Attr(name string) (string, bool) {
	var document map[string]json.RawMessage
	if err := json.Unmarshal(s.Document, &document); err != nil {
		return "", false
	}
	raw, ok := document[name]
	if !ok {
		return "", false
	}
	var text string
	if err := json.Unmarshal(raw, &text); err == nil {
		return text, true
	}
	return string(raw), true
}
